/**
 * =========================================================================
 * GOOGLE APPS SCRIPT: Multi-Year Strategic Health KPI Database (2566–2570)
 * ระบบจัดการและเชื่อมต่อฐานข้อมูลตัวชี้วัดยุทธศาสตร์สุขภาพ สสจ.ขอนแก่น
 * =========================================================================
 * 
 * 📌 คำแนะนำการใช้งาน (Instructions):
 * 1. เปิด Google Sheet ของท่าน (https://docs.google.com/spreadsheets/d/...)
 * 2. ไปที่เมนู "ส่วนขยาย" (Extensions) -> "Apps Script"
 * 3. ลบโค้ดเดิมทั้งหมดในไฟล์ Code.gs แล้วคัดลอกโค้ดนี้ทั้งหมดไปวาง
 * 4. [ขั้นตอนสำคัญครั้งแรก]: เลือกฟังก์ชัน 'createAllKpiSheets' ที่แถบด้านบน แล้วกดปุ่ม "เรียกใช้" (Run)
 *    - ระบบจะสร้างแท็บ KPI_2566, KPI_2567, KPI_2568, KPI_2569, KPI_2570
 *    - พร้อมตั้งหัวคอลัมน์ A-M จัดรูปแบบสี และใส่ข้อมูลตัวชี้วัดตั้งต้นให้โดยอัตโนมัติ!
 * 5. กดปุ่ม "ทำให้ใช้งานได้" (Deploy) -> "การทำให้ใช้งานได้จริงใหม่" (New deployment)
 *    - ประเภท: เว็บแอป (Web app)
 *    - ปฏิบัติการในฐานะ: ตัวฉัน (Me)
 *    - ผู้ที่มีสิทธิ์เข้าถึง: ทุกคน (Anyone)
 * 6. คัดลอก Web App URL ไปใส่ในหน้า WebApp Dashboard เพื่อเชื่อมต่อแบบ Real-time
 * =========================================================================
 */

// รายชื่อแท็บแยกรายปี
const YEAR_SHEETS = {
  '2566': 'KPI_2566',
  '2567': 'KPI_2567',
  '2568': 'KPI_2568',
  '2569': 'KPI_2569',
  '2570': 'KPI_2570',
  '66': 'KPI_2566',
  '67': 'KPI_2567',
  '68': 'KPI_2568',
  '69': 'KPI_2569',
  '70': 'KPI_2570'
};

// คอลัมน์มาตรฐาน A - M
const STANDARD_HEADERS = [
  'KPI_ID',           // A: รหัสตัวชี้วัด
  'Order',            // B: ลำดับ
  'Strategy',         // C: ยุทธศาสตร์
  'Objective',        // D: เป้าประสงค์
  'KPI_Name',         // E: ชื่อตัวชี้วัด
  'Unit',             // F: หน่วยนับ
  'Direction',        // G: ทิศทาง (ยิ่งมากยิ่งดี / ยิ่งน้อยยิ่งดี)
  'Baseline',         // H: ข้อมูลพื้นฐาน
  'Target',           // I: ค่าเป้าหมาย
  'Actual',           // J: ผลงานจริง
  'Status',           // K: สถานะการดำเนินงาน
  'Responsible_Dept', // L: กลุ่มงาน/ผู้รับผิดชอบ
  'Note_Revision'     // M: หมายเหตุ/การปรับปรุง
];

/**
 * =========================================================================
 * 1. ฟังก์ชันสร้าง 5 แท็บอัตโนมัติ (1-Click Automated Setup Function)
 * =========================================================================
 */
function createAllKpiSheets() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const years = ['2566', '2567', '2568', '2569', '2570'];
  
  // Theme Colors
  const headerBgColor = '#1e293b'; // Slate 800
  const headerTextColor = '#ffffff';
  
  years.forEach(year => {
    const sheetName = 'KPI_' + year;
    let sheet = ss.getSheetByName(sheetName);
    
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
    }
    
    // ตั้งค่าหัวตารางแถวที่ 1
    sheet.getRange(1, 1, 1, STANDARD_HEADERS.length).setValues([STANDARD_HEADERS]);
    
    // จัดรูปแบบ Header
    const headerRange = sheet.getRange(1, 1, 1, STANDARD_HEADERS.length);
    headerRange.setBackground(headerBgColor)
               .setFontColor(headerTextColor)
               .setFontWeight('bold')
               .setFontSize(10)
               .setFontFamily('Sarabun')
               .setHorizontalAlignment('center')
               .setVerticalAlignment('middle')
               .setWrap(true);
    
    sheet.setRowHeight(1, 40);
    sheet.setFrozenRows(1);
    
    // ปรับความกว้างคอลัมน์
    sheet.setColumnWidth(1, 100); // KPI_ID
    sheet.setColumnWidth(2, 60);  // Order
    sheet.setColumnWidth(3, 140); // Strategy
    sheet.setColumnWidth(4, 140); // Objective
    sheet.setColumnWidth(5, 380); // KPI_Name
    sheet.setColumnWidth(6, 90);  // Unit
    sheet.setColumnWidth(7, 110); // Direction
    sheet.setColumnWidth(8, 100); // Baseline
    sheet.setColumnWidth(9, 110); // Target
    sheet.setColumnWidth(10, 110);// Actual
    sheet.setColumnWidth(11, 130);// Status
    sheet.setColumnWidth(12, 180);// Responsible_Dept
    sheet.setColumnWidth(13, 200);// Note_Revision
    
    // ตรวจสอบว่าถ้ายังไม่มีข้อมูล ให้ใส่ข้อมูลเริ่มต้นของปีนั้นๆ
    const lastRow = sheet.getLastRow();
    if (lastRow <= 1) {
      const defaultRows = getInitialDataForYear(year);
      if (defaultRows && defaultRows.length > 0) {
        sheet.getRange(2, 1, defaultRows.length, STANDARD_HEADERS.length).setValues(defaultRows);
        
        // จัดรูปแบบเนื้อหาข้อมูล
        const dataRange = sheet.getRange(2, 1, defaultRows.length, STANDARD_HEADERS.length);
        dataRange.setFontFamily('Sarabun').setFontSize(10).setVerticalAlignment('middle');
        
        // Alignment
        sheet.getRange(2, 1, defaultRows.length, 2).setHorizontalAlignment('center'); // KPI_ID, Order
        sheet.getRange(2, 6, defaultRows.length, 6).setHorizontalAlignment('center'); // Unit, Direction, Base, Target, Actual, Status
        sheet.getRange(2, 5, defaultRows.length, 1).setWrap(true); // KPI_Name wrap
      }
    }
  });

  // สร้างชีต Activity_Logs เพื่อเก็บประวัติการแก้ข้อมูล
  let logSheet = ss.getSheetByName('Activity_Logs');
  if (!logSheet) {
    logSheet = ss.insertSheet('Activity_Logs');
    logSheet.appendRow(['Timestamp', 'Year', 'KPI_ID', 'Target', 'Actual', 'Status', 'Notes', 'Updated_By']);
    logSheet.getRange(1, 1, 1, 8).setFontWeight('bold').setBackground('#0f172a').setFontColor('#ffffff');
    logSheet.setFrozenRows(1);
  }

  return 'สร้างและจัดรูปแบบแท็บ KPI_2566 - KPI_2570 เรียบร้อยสมบูรณ์!';
}

/**
 * =========================================================================
 * 2. API GET: ดึงข้อมูลตัวชี้วัดรายปี หรือทั้งหมด (REST API Endpoint)
 * =========================================================================
 */
function doGet(e) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const params = (e && e.parameter) ? e.parameter : {};
    const requestedYear = (params.year || '2568').toString().trim();
    
    // กรณีขอข้อมูลทุกปีพร้อมกัน (?year=all)
    if (requestedYear.toLowerCase() === 'all') {
      const allData = {};
      ['2566', '2567', '2568', '2569', '2570'].forEach(y => {
        allData[y] = readSheetKpis(ss, 'KPI_' + y);
      });
      return createJsonResponse({
        status: 'success',
        type: 'ALL_YEARS',
        timestamp: new Date().toISOString(),
        data: allData
      });
    }

    // แปลงชื่อแท็บจากพารามิเตอร์ปี
    const targetSheetName = YEAR_SHEETS[requestedYear] || ('KPI_' + requestedYear);
    const sheetData = readSheetKpis(ss, targetSheetName);

    return createJsonResponse({
      status: 'success',
      year: requestedYear,
      sheetName: targetSheetName,
      totalKpis: sheetData.length,
      timestamp: new Date().toISOString(),
      data: sheetData
    });

  } catch (error) {
    return createJsonResponse({ status: 'error', message: error.toString() });
  }
}

/**
 * Helper: อ่านข้อมูลแถวทั้งหมดจากชีตรายปี
 */
function readSheetKpis(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];

  const values = sheet.getDataRange().getValues();
  if (!values || values.length <= 1) return [];

  const rows = values.slice(1); // ข้าม Header แถวที่ 1
  const kpiList = [];

  rows.forEach((row, index) => {
    const id = row[0] ? row[0].toString().trim() : '';
    if (!id) return;

    kpiList.push({
      id: id,
      order: row[1] ? row[1].toString().trim() : (index + 1).toString(),
      strategy: row[2] ? row[2].toString().trim() : '',
      objective: row[3] ? row[3].toString().trim() : '',
      name: row[4] ? row[4].toString().trim() : '',
      unit: row[5] ? row[5].toString().trim() : '',
      direction: row[6] ? row[6].toString().trim() : 'ยิ่งมากยิ่งดี',
      baseline: row[7] !== undefined && row[7] !== '' ? row[7] : null,
      target: row[8] !== undefined && row[8] !== '' ? row[8] : null,
      actual: row[9] !== undefined && row[9] !== '' ? row[9] : null,
      status: row[10] ? row[10].toString().trim() : '',
      responsibleDept: row[11] ? row[11].toString().trim() : '',
      notes: row[12] ? row[12].toString().trim() : ''
    });
  });

  return kpiList;
}

/**
 * =========================================================================
 * 3. API POST: บันทึก/อัปเดตข้อมูลเป้าหมายหรือผลงานรายตัวชี้วัด
 * =========================================================================
 */
function doPost(e) {
  try {
    const postData = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    
    const year = (postData.year || '2569').toString().trim();
    const sheetName = YEAR_SHEETS[year] || ('KPI_' + year);
    const sheet = ss.getSheetByName(sheetName);

    if (!sheet) {
      return createJsonResponse({ status: 'error', message: 'Sheet not found: ' + sheetName });
    }

    const kpiId = postData.id;
    if (!kpiId) {
      return createJsonResponse({ status: 'error', message: 'KPI ID is required' });
    }

    const data = sheet.getDataRange().getValues();
    let targetRowNumber = -1;
    for (let r = 1; r < data.length; r++) {
      if (data[r][0] && data[r][0].toString().trim() === kpiId) {
        targetRowNumber = r + 1; // 1-based index in Sheet
        break;
      }
    }

    if (targetRowNumber === -1) {
      return createJsonResponse({ status: 'error', message: 'KPI ID not found in sheet: ' + kpiId });
    }

    // อัปเดต Target (คอลัมน์ I = 9)
    if (postData.target !== undefined) {
      sheet.getRange(targetRowNumber, 9).setValue(postData.target);
    }
    // อัปเดต Actual (คอลัมน์ J = 10)
    if (postData.actual !== undefined) {
      sheet.getRange(targetRowNumber, 10).setValue(postData.actual);
    }
    // อัปเดต Status (คอลัมน์ K = 11)
    if (postData.status !== undefined) {
      sheet.getRange(targetRowNumber, 11).setValue(postData.status);
    }
    // อัปเดต หมายเหตุ (คอลัมน์ M = 13)
    if (postData.notes !== undefined) {
      sheet.getRange(targetRowNumber, 13).setValue(postData.notes);
    }

    // บันทึก Activity Log
    logMultiYearActivity(ss, year, kpiId, postData.target, postData.actual, postData.status, postData.notes, postData.updatedBy || 'Web User');

    return createJsonResponse({
      status: 'success',
      message: 'Updated KPI ' + kpiId + ' in ' + sheetName + ' successfully',
      updatedAt: new Date().toISOString()
    });

  } catch (error) {
    return createJsonResponse({ status: 'error', message: error.toString() });
  }
}

function logMultiYearActivity(ss, year, kpiId, target, actual, status, notes, user) {
  try {
    let logSheet = ss.getSheetByName('Activity_Logs');
    if (!logSheet) {
      logSheet = ss.insertSheet('Activity_Logs');
      logSheet.appendRow(['Timestamp', 'Year', 'KPI_ID', 'Target', 'Actual', 'Status', 'Notes', 'Updated_By']);
    }
    logSheet.appendRow([new Date(), year, kpiId, target || '', actual || '', status || '', notes || '', user]);
  } catch (e) {
    Logger.log('Log error: ' + e);
  }
}

function createJsonResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

